     */
    public static function getAppKey(): string
    {
        if (self::$cachedKey !== null) {
            return self::$cachedKey;
        }

        $configDir = realpath(__DIR__ . '/../../config');
        if ($configDir === false) {
            $configDir = dirname(__DIR__, 2) . DIRECTORY_SEPARATOR . 'config';
        }
        $keyFile = $configDir . DIRECTORY_SEPARATOR . 'app_key.php';

        if (file_exists($keyFile)) {
            $encoded = include $keyFile;
            if (is_string($encoded) && !empty($encoded)) {
                $raw = base64_decode($encoded, true);
                if ($raw !== false && strlen($raw) === 32) {
                    self::$cachedKey = $raw;
                    return self::$cachedKey;
                }
            }
