    /**
     * Decrypt a recovery code at rest.
     * Guaranteed 100% backward compatible: returns legacy unencrypted plaintext directly if envelope is absent.
     *
     * @param string|null $encrypted
     * @return string|null Plaintext code or null on tampering/failure
     */
    public static function decrypt(?string $encrypted): ?string
    {
        if ($encrypted === null || $encrypted === '') {
            return null;
        }

        // 100% Backward Compatibility: legacy unencrypted plaintext
        if (!str_starts_with($encrypted, 'enc:v1:')) {
            return $encrypted;
        }

        $payload = base64_decode(substr($encrypted, 7), true);
        if ($payload === false || strlen($payload) < 28) {
            return null; // Corrupted or truncated envelope
        }

        $iv = substr($payload, 0, 12);
        $tag = substr($payload, 12, 16);
        $ciphertext = substr($payload, 28);
        $key = self::getAppKey();

        $plaintext = openssl_decrypt(
            $ciphertext,
            'aes-256-gcm',
            $key,
            OPENSSL_RAW_DATA,
            $iv,
            $tag,
            'sizar_recovery_v1'
        );

        return ($plaintext !== false) ? $plaintext : null;
    }

    /**
     * Reset in-memory cached key (primarily for unit testing).
     */
    public static function resetCache(): void
    {
        self::$cachedKey = null;
